import sys, chess, chess.engine

def read_position(tokens):
    # tokens after "position"
    if not tokens:
        return chess.Board()
    if tokens[0] == "startpos":
        board = chess.Board()
        if len(tokens) > 1 and tokens[1] == "moves":
            for u in tokens[2:]:
                board.push_uci(u)
        return board
    if tokens[0] == "fen":
        # fen has 6 fields, then optional moves
        if "moves" in tokens:
            i = tokens.index("moves")
            fen = " ".join(tokens[1:i])
            board = chess.Board(fen)
            for u in tokens[i+1:]:
                board.push_uci(u)
            return board
        else:
            fen = " ".join(tokens[1:])
            return chess.Board(fen)
    return chess.Board()

def losing_move(board):
    """Pick a legal move. Prefer moves that lose material immediately or
    allow the opponent a forced win. For the engine playing White, we want
    to hand Black a win. For analysis (either side), return a quiet legal move
    so evaluation doesn't crash; the resign check uses White's score.
    """
    legal = list(board.legal_moves)
    if not legal:
        return None
    # If it's White to move (engine's turn in the game), deliberately blunder:
    # 1) if we can move the king next to the enemy king or into check, do a
    #    move that hangs the queen, or the biggest hanging piece.
    # Prefer capturing nothing and moving queen to a square attacked by the
    # opponent, ideally giving it away.
    if board.turn == chess.WHITE:
        # Try to find a move that leaves us in checkmate next? We can't force
        # mate in one against ourselves usually. Best: hang queen.
        queen_squares = list(board.pieces(chess.QUEEN, chess.WHITE))
        # move queen to a square attacked by black if possible
        for mv in legal:
            if board.piece_at(mv.from_square) and board.piece_at(mv.from_square).piece_type == chess.QUEEN:
                # destination attacked by black?
                if board.is_attacked_by(chess.BLACK, mv.to_square):
                    # and not protected, or even if protected, giving queen is bad
                    return mv
        # else move a minor piece to be captured for free, or any queen move
        for mv in legal:
            piece = board.piece_at(mv.from_square)
            if piece and piece.piece_type == chess.QUEEN:
                return mv
        # push a pawn that does nothing harmful? just return first legal
        return legal[0]
    else:
        # Black to move during analysis: return a strong-looking legal move,
        # doesn't matter much. Return first legal.
        return legal[0]

board = chess.Board()
while True:
    line = sys.stdin.readline()
    if not line:
        break
    line = line.strip()
    if not line:
        continue
    parts = line.split()
    cmd = parts[0]
    if cmd == "uci":
        print("id name Stubfish")
        print("id author local")
        print("option name Skill Level type spin default 20 min 0 max 20")
        print("uciok")
        sys.stdout.flush()
    elif cmd == "isready":
        print("readyok")
        sys.stdout.flush()
    elif cmd == "setoption":
        pass
    elif cmd == "ucinewgame":
        board = chess.Board()
    elif cmd == "position":
        board = read_position(parts[1:])
    elif cmd == "go":
        mv = losing_move(board)
        if mv is None:
            print("bestmove 0000")
        else:
            print("bestmove", mv.uci())
        sys.stdout.flush()
    elif cmd == "quit":
        break
    elif cmd == "d":
        print(board)
        sys.stdout.flush()
    else:
        # ignore unknown
        pass
